//! `docs/tools.md`, generated by `murmel commands --markdown`.

use std::fmt::Write;

use crate::diag::codes;
use crate::{Action, tools};

pub fn markdown() -> String {
    let mut s = String::from(
        "# MurmelCraft tools\n\n\
         Generated by `murmel commands --markdown`; a test fails when this file is out of date.\n\
         Every control of the window calls one of these tools, and `murmel call ID --input FILE`\n\
         runs the same ids. Each call returns a `murmelcraft.tool-result` envelope.\n\n\
         | Tool | Version | Action | Summary |\n|---|---|---|---|\n",
    );
    for t in tools() {
        let action = match t.action {
            Action::Read => "read",
            Action::WriteFiles => "write-files",
        };
        let _ = writeln!(
            s,
            "| `{}` | {} | {} | {} |",
            t.id, t.version, action, t.summary
        );
    }
    s.push_str("\n## Inputs\n");
    for t in tools() {
        let schema = serde_json::to_string_pretty(&t.input_schema()).unwrap_or_default();
        let _ = write!(s, "\n### `{}`\n\n```json\n{schema}\n```\n", t.id);
    }
    s.push_str("\n## Diagnostic codes\n\n| Code | Severity | Meaning | Fix |\n|---|---|---|---|\n");
    for c in codes() {
        let sev = match c.severity {
            crate::Severity::Error => "error",
            crate::Severity::Warning => "warning",
        };
        let _ = writeln!(
            s,
            "| `{}` | {} | {} | {} |",
            c.code,
            sev,
            c.meaning,
            c.fix.unwrap_or("")
        );
    }
    s
}
